echo '--- Downloading PolicyStore from Artifactory on ${bamboo.OES_HOSTNAME} ---';
ssh   -o UserKnownHostsFile=/dev/null -o StrictHostKeyChecking=no  ${bamboo.OES_HOSTNAME} "sudo -u oracle -- sh -c 'set -e ; source /home/oracle/.bash_profile ; rm -rf /oracle/app/binaries/pit; mkdir -p /oracle/app/binaries/pit/PolicyStoreSetup; cd /oracle/app/binaries/pit/PolicyStoreSetup; wget --no-check-certificate ${bamboo.ARTIFACTORY_URL}/${bamboo.CEMLI_RELEASE_PATH}/extensionspolicystoresetup/${bamboo.POLICY_VERSION}/extensionspolicystoresetup-${bamboo.POLICY_VERSION}.tar.gz -O PolicyStoreSetup.tar.gz'";
echo '--- Setting up PolicyStore on ${bamboo.OES_HOSTNAME} ---';
ssh   -o UserKnownHostsFile=/dev/null -o StrictHostKeyChecking=no  ${bamboo.OES_HOSTNAME} "sudo -u oracle -- sh -c 'set -e ; source /home/oracle/.bash_profile ; cd /oracle/app/binaries/pit/PolicyStoreSetup; tar -zxvf PolicyStoreSetup.tar.gz'";
echo '--- Starting Policy Import on ${bamboo.OES_HOSTNAME} ---';
ssh    -o UserKnownHostsFile=/dev/null -o StrictHostKeyChecking=no ${bamboo.OES_HOSTNAME} "sudo -u oracle -- sh -c 'set -e ; source /home/oracle/.bash_profile ; cd /oracle/app/binaries/pit/PolicyStoreSetup/UtilityConfig; unzip -o UIComponents_new.zip'";
echo '---Executing gradle for customisation and execution of PolicyStore---';
ssh    -o UserKnownHostsFile=/dev/null -o StrictHostKeyChecking=no ${bamboo.OES_HOSTNAME} "sudo -u oracle -- sh -c 'set -e ; source /home/oracle/.bash_profile ;   cd ${bamboo.OBP_DEPLOY_HOME}; chmod 755 scripts/* ; ${bamboo.GRADLE_HOME}/bin/gradle -b obpAccessPolicyDeploy.gradle -PmintDeployHome=/oracle/app/binaries/deployments/mintdeploy -PfetchTargets=true -PenvName=LOCAL -PconfigProviderPath=../../deploymentProperties/eng10/obpht.json deploy clean -s'";
ssh    -o UserKnownHostsFile=/dev/null -o StrictHostKeyChecking=no ${bamboo.OES_HOSTNAME} "sudo -u oracle -- sh -c 'set -e ; source /home/oracle/.bash_profile ; cd /oracle/app/binaries/pit/PolicyStoreSetup; chmod 755 seedFreshPolicyStore.sh; ./seedFreshPolicyStore.sh'";
echo '--- Finished Policy Import on ${bamboo.OES_HOSTNAME} ---';
